actions.script:
import org.moqui.impl.util.RestSchemaUtil

Map toolMap = [:]

// 1. DIRECT SERVICE INSPECTION FOR org.moqui.ai.mcp.* SERVICES
def serviceFacade = ec.factory.serviceFacade
def knownServices = serviceFacade.getKnownServiceNames()

for (String sName in knownServices) {
    if (sName.startsWith("org.moqui.ai.mcp.")) {
        def sd = serviceFacade.getServiceDefinition(sName)
        if (sd != null) {
            def parts = sName.split("\\.")
            def rawName = parts[parts.length - 1].replace("#", "_")
            def cleanMethodName = rawName.replaceAll("([a-z])([A-Z])", '$1_$2').toLowerCase()

            def description = sd.serviceNode.attribute("description") ?: sd.serviceNode.first("description")?.getText() ?: "MCP tool for ${sName}"

            // Derive read-only capability from service verb/noun
            String verb = sd.verb?.toLowerCase() ?: ""
            String noun = sd.noun?.toLowerCase() ?: ""
            boolean isReadOnly = verb.startsWith("get") || verb.startsWith("find") || verb.startsWith("search") ||
                                 verb.startsWith("list") || verb.startsWith("validate") || noun.contains("search") ||
                                 noun.contains("list") || noun.contains("archetype")

            // Use framework standard RestSchemaUtil (matches ServiceCallTool)
            Map schema = RestSchemaUtil.getJsonSchemaMapIn(sd) ?: [type: "object", properties: [:]]

            // Enhance schema parameter descriptions with canonical formatting hints
            if (schema.properties instanceof Map) {
                schema.properties.each { pName, pDef ->
                    if (pDef instanceof Map && (pName.equalsIgnoreCase("artifactUri") || pName.equalsIgnoreCase("targetScreenUri"))) {
                        pDef.description = (pDef.description ?: pName) + " (Required format: 'component://<componentName>/screen/<path>.xml')"
                    }
                }
            }

            toolMap[cleanMethodName] = [
                name           : cleanMethodName,
                command        : "/" + cleanMethodName.replace("_", "-"),
                serviceName    : sName,
                serviceCallName: sName, // Standardized key consumed by executeOpenAiProxyLoop
                readOnly       : isReadOnly,
                isReadOnly     : isReadOnly,
                title          : cleanMethodName.replace("_", " ").capitalize(),
                description    : description.trim() + " NOTE: Pass exact parameter names matching the schema.",
                inputSchema    : schema
            ]
        }
    }
}

// 2. OPTIONAL: QUERY moqui-mcp CATALOG
try {
    def mcpRes = ec.service.sync().name("McpServices.list#Tools").call()
    def mcpToolsList = mcpRes?.result?.tools ?: mcpRes?.tools ?: []

    mcpToolsList.each { mcpTool ->
        String tName = mcpTool.name
        if (tName && !toolMap.containsKey(tName)) {
            boolean isReadOnly = mcpTool.readOnly == true || mcpTool.isReadOnly == true
            toolMap[tName] = [
                name           : tName,
                command        : "/" + tName.replace("_", "-"),
                serviceName    : "McpServices.mcp#ToolsCall",
                serviceCallName: "McpServices.mcp#ToolsCall",
                readOnly       : isReadOnly,
                isReadOnly     : isReadOnly,
                isMcpWrapper   : true,
                title          : tName.replace("_", " ").capitalize(),
                description    : mcpTool.description ?: "moqui-mcp tool",
                inputSchema    : mcpTool.inputSchema ?: [type: "object", properties: [:]]
            ]
        }
    }
} catch (Exception ex) {
    ec.logger.warn("⚠️ Error inspecting McpServices.list#Tools catalog: " + ex.message)
}

context.tools = new ArrayList(toolMap.values())

Map callParams = parameters ?: [:]

if (serviceName == "McpServices.mcp#ToolsCall") {
    String actualToolName = toolName ?: callParams.remove("toolName") ?: callParams.remove("name")
    Map result = ec.service.sync().name("McpServices.mcp#ToolsCall").parameters([
        name: actualToolName,
        arguments: callParams
    ]).call()
    context.putAll(result?.result ?: result ?: [:])
    return
}

if (!serviceName.startsWith("org.moqui.ai.mcp.")) {
    ec.message.addError("Unauthorized service execution: " + serviceName)
    return
}

Map result = ec.service.sync().name(serviceName).parameters(callParams).call()
context.putAll(result)
